// Reads the lead id from the link (GET) or the confirm button (POST) and validates its format.
// Lee el id del lead del link (GET) o del botón (POST) y valida el formato.
const req = $input.first().json;
const raw = String((req.body && req.body.id) || (req.query && req.query.id) || '').trim();
const lead_id = /^LUM-\d{8}-[A-Z0-9]{3,10}$/.test(raw) ? raw : '';
const step = req.body && req.body.id ? 'confirm' : 'ask';
return [{ json: { lead_id, step } }];

// Finds the lead in Leads and prepares the opt-out (estado = opt_out stops every channel).
// Busca el lead en Leads y prepara la baja (estado = opt_out detiene todos los canales).
const id = $('Unsubscribe Gate').first().json.lead_id;
const v = $input.first().json.values || [];
const h = v[0] || [];
const col = name => h.indexOf(name);
const idx = v.findIndex((r, k) => k > 0 && r[col('lead_id')] === id);
if (idx < 1) return [{ json: { found: false } }];          // unknown id: same neutral page / misma página neutra
const letter = n => String.fromCharCode(65 + n);            // A-Z is enough (16 columns)
const row = idx + 1;
const now = $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss');
return [{ json: {
  found: true, lead_id: id, estado_anterior: v[idx][col('estado')] || '',
  body: { valueInputOption: 'RAW', data: [
    { range: `Leads!${letter(col('estado'))}${row}`, values: [['opt_out']] },
    { range: `Leads!${letter(col('ultima_actualizacion'))}${row}`, values: [[now]] }
  ] }
} }];

// Builds the unsubscribe pages. Step 1 (GET) only shows a confirm button: email security scanners open
// links automatically, so a plain GET must never unsubscribe anyone. Step 2 (POST) shows the result.
// Arma las páginas de baja. Paso 1 (GET): solo un botón de confirmación (los filtros de correo abren los
// links solos, así que un GET nunca da de baja a nadie). Paso 2 (POST): muestra el resultado.
const page = inner => '<!doctype html><html lang="es"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width, initial-scale=1"><title>Lumière Aesthetics</title><link href="https://fonts.googleapis.com/css2?family=Libre+Caslon+Condensed:wght@400&family=Inter:wght@400;500&display=swap" rel="stylesheet"><style>'
  + 'body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#F7F3EE;font-family:Inter,Helvetica,Arial,sans-serif;color:#2A2420;padding:16px;box-sizing:border-box}'
  + 'main{max-width:440px;background:#fff;padding:48px 32px;border:1px solid #DDD2C4;text-align:center}'
  + 'h1{font-family:\'Libre Caslon Condensed\',Georgia,serif;font-weight:400;font-size:40px;line-height:1;margin:0 0 6px}h1+small{display:block;font-size:11px;letter-spacing:.3em;color:#75685C;margin:0 0 32px}p{line-height:1.6;margin:0 0 24px}span{color:#75685C;font-size:14px}'
  + 'button{background:#2A2420;color:#fff;border:0;border-radius:0;padding:16px 32px;font-size:12px;letter-spacing:.2em;text-transform:uppercase;cursor:pointer;font-family:inherit}'
  + '</style></head><body><main><h1>Lumière</h1><small>AESTHETICS</small>' + inner + '</main></body></html>';

const isConfirm = $('Unsubscribe Gate').first().json.step === 'confirm';
const id = $('Unsubscribe Gate').first().json.lead_id;
let inner;
if (!id) inner = '<p>Este enlace no es válido.<br><span>This link is not valid.</span></p>';
else if (!isConfirm) inner = '<p>¿Quieres dejar de recibir correos de Lumière Aesthetics?<br><span>Do you want to stop receiving emails from Lumière Aesthetics?</span></p>'
  + '<form method="POST"><input type="hidden" name="id" value="' + id + '"><button type="submit">Darme de baja / Unsubscribe</button></form>';
else inner = '<p>Listo, ya no te enviaremos más correos.<br><span>Done, you will not receive more emails from us.</span></p>'
  + '<p><span>Si cambias de opinión, escríbenos por WhatsApp. / If you change your mind, message us on WhatsApp.</span></p>';

return [{ json: { html: page(inner) } }];
